    function initMasterData() {
        try {
            // 1. Ingredients
            const existingIngs = Store.getIngredients();
            if (!existingIngs || existingIngs.length < 50) {
                if (MASTER_DATA.inv_ingredients && MASTER_DATA.inv_ingredients.length > 0) {
                    localStorage.setItem(Store.KEYS.INGREDIENTS, JSON.stringify(MASTER_DATA.inv_ingredients));
                }
            }

            // 2. Categories
            const existingCats = Store.getCategories();
            if (!existingCats || existingCats.length < 15) {
                if (MASTER_DATA.inv_categories && MASTER_DATA.inv_categories.length > 0) {
                    localStorage.setItem(Store.KEYS.CATEGORIES, JSON.stringify(MASTER_DATA.inv_categories));
                }
            }

            // 3. Warehouses
            const existingWhs = Store.getWarehouses();
            if (!existingWhs || existingWhs.length < 2) {
                if (MASTER_DATA.inv_warehouses && MASTER_DATA.inv_warehouses.length > 0) {
                    localStorage.setItem(Store.KEYS.WAREHOUSES, JSON.stringify(MASTER_DATA.inv_warehouses));
                }
            }

            // 4. Opening Balances
            const curMonth = new Date().getFullYear() + '-' + String(new Date().getMonth() + 1).padStart(2, '0');
            const existingBalances = Store.getOpeningBalances(curMonth);
            if (!existingBalances || Object.keys(existingBalances).length === 0) {
                if (MASTER_DATA.inv_opening_balances) {
                    localStorage.setItem(Store.KEYS.OPENING_BALANCES, JSON.stringify(MASTER_DATA.inv_opening_balances));
                }
            }

            // 5. Purchases
            const existingPurchases = Store.getPurchases();
            if (!existingPurchases || existingPurchases.length === 0) {
                if (MASTER_DATA.inv_purchases && MASTER_DATA.inv_purchases.length > 0) {
                    localStorage.setItem(Store.KEYS.PURCHASES, JSON.stringify(MASTER_DATA.inv_purchases));
                }
            }

            // 6. Admin Account
            let employees = Store.getEmployees();
            let admin = employees.find(e => e.username?.toLowerCase() === 'ahmed.admin');
            if (!admin || !admin.password) {
                if (!admin) {
                    Store.saveEmployee({
                        id: "admin-ahmed-master",
                        name: "أحمد بن سعيد",
                        username: "Ahmed.admin",
                        password: "aaaaaaaa",
                        role: "admin",
                        phone: "91234567",
                        allowedTabs: ["all"]
                    });
                } else {
                    admin.password = "aaaaaaaa";
                    Store.saveEmployee(admin);
                }
            }
        } catch(e) {
            console.error("Master seed error:", e);
        }
    }

    initMasterData();
